"""Layer 15 MLP down_proj, component 4676: a "make" and content-verb detector.

Rough sketch, not a full account. Word and neighbour rules explain about 4% of this
component's variance (a per-token table tops out near 7%); most of the rest is diffuse.

What it responds to, on training text:
- The verb "make" (make, makes, making) used as an active verb: strong after "to",
  "and", "that", a modal, or a pronoun ("to make learning fun": about 4.5). Weak after
  a be-form or a determiner ("the make-up", "is making"): about 1.
- "made" as a participle is about half as strong (2.3), and weak after a be-form ("is made").
- Other content verbs (WordNet verbs that are not auxiliaries: keep, get, know, take,
  explain, identify, ...): about 1.2 after "to" ("the ability to explain"), about 0.4
  after a pronoun, modal, "and" or "that", and about -0.1 after a determiner, where the
  word is a noun.
- Everything else, including most nouns and function words, is 0.

step() returns one activation per position; it uses only the current word and the one
before it, within the same document.
"""

import wordnet

READS = ()

MAKE = {"make", "makes", "making"}
BE = {"is", "are", "was", "were", "be", "been", "being", "am"}
AUX = BE | {"has", "have", "had", "does", "did", "can", "could", "will", "would",
            "shall", "should", "may", "might", "must"}
DETERMINERS = {"the", "a", "an", "this", "these", "those", "its", "their", "your", "my",
               "our", "his", "her", "every", "each", "some", "any"}
SUBJECT_OR_MODAL = {"can", "will", "would", "should", "must", "could", "may", "might",
                    "please", "not", "and", "that", "which", "if", "we", "you", "they",
                    "i", "he", "she", "it"}


def is_content_verb(word):
    """True for an English word that WordNet lists as a verb (or a form of one), not an auxiliary."""
    if not word.isascii() or not word.isalpha() or word in AUX:
        return False
    lemmas = set(wordnet.base_forms(word)) | {word}
    return any("verb" in wordnet.parts_of_speech(lemma) for lemma in lemmas)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in MAKE:
        return carry, (1.0 if prev in BE or prev in DETERMINERS else 4.5)
    if word == "made":
        return carry, (0.8 if prev in BE else 2.3)
    if is_content_verb(word):
        if prev == "to":
            return carry, 1.2
        if prev in SUBJECT_OR_MODAL:
            return carry, 0.4
        if prev in DETERMINERS:
            return carry, -0.1
    return carry, 0.0

"""Layer-15 MLP down-projection component 4685: a signed feature that is large on
document ends, web-page furniture, line breaks and clock/year digits, and negative on
the chat role word 'assistant'. Its size fades with distance into the document.

Plain-terms rule (the values marked * are scaled by how early in the document the token is;
the document-end and role values are not):
  * <|endoftext|> (document boundary):            strongly positive  (about +6)
  * 'assistant' (chat-template role word):        strongly negative  (about -4)
  * digits inside a clock time, e.g. '2' of 15:22: positive*         (about +3)
  * the last digit of a year, e.g. '4' of 2014:   weakly positive*  (about +1)
  * web/forum labels and markers (Posted, Joined, Tags, References,
    ###, bullets, AM/PM):                          positive*          (about +2 / +0.7)
  * line breaks (\\n, \\n\\n):                       weakly positive*   (about +0.35)
  * everything else:                              0
Scale: x2.5 for tokens 1-3 of a document, x1.5 for tokens 4-15, then x1.
The first token of each document is 0.
"""
import re

READS = ()

WEB_LABELS = {
    "Posted", "Joined", "Posts", "Post", "Pages", "Page", "Replies", "Reply", "Tags",
    "Views", "View", "Downloads", "Ratings", "Question", "Answer", "Published",
    "Copyright", "permalink", "References", "Abstract", "Comments", "Comment",
    "Kudos", "Offline", "Online", "Likes", "Shares", "Filed", "Related", "Sponsored",
}
MARKERS = {"•", "·", "|", "||", "|\n", "AM", "PM", "am", "pm"}
TEXT_LEN = 4  # characters of recent text kept, enough to see 'd:' or '20'


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        pos, before = 0, ""
    else:
        pos, before = carry["pos"] + 1, carry["recent"]
    recent = (before + tok)[-TEXT_LEN:]
    new = {"doc": doc, "pos": pos, "recent": recent}
    if pos == 0:
        return new, 0.0

    gain = 2.5 if pos <= 3 else 1.5 if pos <= 15 else 1.0
    digit = re.fullmatch(r"\d", tok) is not None
    if tok == "<|endoftext|>":
        value = 6.2
    elif tok == "assistant":
        value = -3.9
    elif digit and re.search(r"\d:\d?$", before):
        value = 3.0 * gain  # minutes of a clock time
    elif digit and re.search(r"(19|20)\d$", before):
        value = 0.9 * gain  # last digits of a year
    elif tok.strip() in WEB_LABELS:
        value = 2.0 * gain
    elif tok.strip() in MARKERS or re.fullmatch(r"#+", tok.strip()):
        value = 0.7 * gain
    elif "\n" in tok:
        value = 0.35 * gain
    else:
        value = 0.0
    return new, float(value)

"""Digit detector: the component fires on decimal digit tokens inside numbers.

Every decimal digit character (0-9, or a fullwidth digit) makes it fire. A number's
first digit fires a little less than a digit that follows another digit of the same
number. Everything else (letters, spaces, punctuation) leaves it near zero, and so does
a digit at the very start of a document, where the model has no earlier text to read.
"""

READS = ()

FIRST_DIGIT = 10.5  # a digit not preceded by another digit
LATER_DIGIT = 14.0  # a digit preceded by another digit


def is_digit(text):
    return len(text) == 1 and text.isdecimal()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if not is_digit(tok) or prefix.position == 0:
        return carry, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    if is_digit(prefix.token_strings[-2]):
        return carry, LATER_DIGIT
    return carry, FIRST_DIGIT

"""Predicate-lead-in detector: negative where a copula or degree adverb sets up an
adjective ("it's [very] [important]", "this is", "they are", "it seems").

Component p-82af68dd@100000/layers.15.mlp.down_proj:4699 writes into the residual
stream with its activation sign set by this context. Its activation is strongly
negative on a linking verb (is, 's, are, be, am, was, 're, 'm, seems, looks, feels)
and on a degree word after one (very, really, too, quite, pretty, so, not). The
size depends on what the subject is:

- "it / this / that / which" + copula: strongest (about -7; about -11 when the
  text is conversational, with I / you / we / me or a question mark nearby).
- another pronoun (they, these, he, she, you, we, there, what, ...): about -3.5.
- a noun or anything else: about -1.5.
- a degree adverb right after a copula: about -9; "not/just/so/still/..." after a
  copula: about -4.

Everything else is 0. The program reads only the current token, the one before it
(within the same document), and a 12-token window for the conversational cue.
"""
from collections.abc import Mapping

READS: tuple[str, ...] = ()

COPULA = {"is", "are", "be", "am", "was", "were", "been", "being", "'s", "’s", "'m", "’m", "'re", "’re"}
DEGREE = {"very", "really", "pretty", "quite", "too", "extremely", "somewhat", "fairly", "absolutely",
          "totally", "rather", "truly", "perfectly", "highly", "relatively", "incredibly"}
AFTER_COPULA = {"not", "just", "so", "still", "always", "also", "more", "most", "exactly", "bit"}
LINKING = {"seems", "seem", "seemed", "looks", "look", "feels", "feel", "sounds", "sound", "appears"}
IT_SUBJECT = {"it", "this", "that", "which"}
PRONOUN_SUBJECT = {"they", "these", "those", "he", "she", "you", "we", "i", "there", "what", "who",
                   "everything", "something", "nothing", "one"}
CONVERSATIONAL = {"i", "you", "we", "me", "my", "your", "?"}


def step(carry, prefix, upstream: Mapping):
    ids = prefix.document_ids
    start = len(ids) - 1  # the last 12 tokens of the same document, newest last
    while start > 0 and start > len(ids) - 13 and ids[start - 1] == ids[-1]:
        start -= 1
    words = [s.strip().lower() for s in prefix.token_strings[start:]]
    word = words[-1]
    before = words[-2] if len(words) > 1 else ""
    if word in COPULA:
        if before in IT_SUBJECT:
            talky = any(w in CONVERSATIONAL for w in words[:-1])
            return carry, (-11.0 if talky else -7.0)
        if before in PRONOUN_SUBJECT:
            return carry, -3.5
        return carry, -1.5
    if word in DEGREE and before in COPULA:
        return carry, -9.0
    if word in AFTER_COPULA and before in COPULA:
        return carry, -4.0
    if word in DEGREE:
        return carry, -5.0
    if word in LINKING:
        return carry, -3.0
    return carry, 0.0

"""Sentence-end detector for ordinary prose (v4).

What it does: the component fires on the full stop, question mark or
exclamation mark that ends a sentence, including one that closes a bracket
or quote (").", ")."). How strongly depends on what the sentence looks like
so far. A sentence made of ordinary lowercase words ("the model was trained
on the data.") drives it hard; a full stop after a number, an abbreviation, a
name or a code/list fragment barely moves it. Commas and paragraph breaks
after a full stop get small values; all other tokens get 0.

Rule, per token:
  - a token ending in "." "?" or "!" (no line break inside): 7 times the share
    of lowercase words in the sentence so far (capped at 80%). A sentence is
    every token since the last sentence end or line break.
  - "。" "？" "！" (CJK sentence ends): 5.
  - "," "，" "、": 0.4.
  - ".\\n\\n" and "?\\n\\n" (full stop then paragraph break): 1.2.
  - anything else: 0.
"""

READS = ()

CJK_END = {"。", "？", "！"}
COMMAS = {",", "，", "、"}
PARA_END = {".\n\n", "?\n\n"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "tokens": 0, "lower_words": 0}
    ends = "\n" not in tok and tok.rstrip()[-1:] in (".", "?", "!")
    value = 0.0
    if ends:
        share = carry["lower_words"] / carry["tokens"] if carry["tokens"] else 0.0
        value = 7.0 * min(share / 0.8, 1.0)
    elif tok in CJK_END:
        value = 5.0
    elif tok in COMMAS:
        value = 0.4
    elif tok in PARA_END:
        value = 1.2
    if ends or tok in CJK_END or "\n" in tok:
        carry = {"doc": doc, "tokens": 0, "lower_words": 0}
    else:
        s = tok.strip()
        lower = s.isalpha() and s.islower()
        carry = {"doc": doc, "tokens": carry["tokens"] + 1, "lower_words": carry["lower_words"] + lower}
    return carry, value

"""Layer 15, MLP hidden unit 4726 (component p-82af68dd@100000/layers.15.mlp.down_proj:4726).

The component is one hidden unit of layer 15's MLP, scaled by the length of its output
column. It is silent on nearly every token. It fires on a one-letter variable name in
mathematics or code, most of all where the variable is being introduced or passed to a
function: the x in "Let f(x) = ...", the i in "for i" or "int i" or x_{i}, the x in f(x).
Lowercase letters fire more than capitals, x and the index letters i, j, k most of all,
and the English word "a" does not fire.

This program reads only the current token and the few tokens before it. It predicts the
component's activation from the following cases, most specific first:
  - the argument of a function being defined: the x in "Let f(x) = ..." (strongest)
  - another argument fused to its function's name: f(x)
  - the index of a sum, product or limit: the i in sum_{i}
  - an index letter (i, j, k) that a loop, declaration or subscript introduces
  - any other variable that such a word or mark introduces: for, int, Let, each, _{
  - a variable right after an opening bracket, dollar sign or similar: ( $ [ { ;
  - any other one-letter variable, and Greek or other math symbols a little
Every other token gets a small negative value, the component's usual resting level.
"""
import re

READS = ()

# A one-letter variable, optionally fused with the bracket, comma or space before it: x, " x", "(x", ",b".
VARIABLE = re.compile(r"[(\[{,\s_]*[A-Za-z]")
# A function argument fused with its opening parenthesis: the "(x" of f(x).
ARGUMENT = re.compile(r"\([A-Za-z]{1,2}")
# A one- or two-letter name, such as f in f(x).
NAME = re.compile(r"[A-Za-z]{1,2}")
# A Greek letter or math symbol.
SYMBOL = re.compile(r"[\u0370-\u03ff±∈µ]")
# English one-letter words that are not variables.
WORDS = {" a", "a", " I", "I"}
# Words that open a definition.
DEFINERS = {"Let", "let", "Define", "define"}
# Words and subscript marks that introduce a variable.
BINDERS = {"for", "int", "(int", "Let", "let", "each", "all", "map", "((", "_{"}
# Index letters.
INDEXES = {"i", "j", "k"}
# Operators whose subscript is an index: the i in sum_{i}, \prod_{i}, \lim_{n}.
INDEXED_BY = {"sum", "Sum", "prod", "product", "lim", "limits"}
# Opening brackets and math or code marks that often come right before a variable.
OPENERS = {"(", "[", "{", "$", "$$", "\\(", ";", "&", "=", "+"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    cur = toks[-1]
    same_doc = len(toks) > 1 and docs[-2] == docs[-1]
    prev = toks[-2].strip() if same_doc else ""
    two_back = toks[-3].strip() if len(toks) > 2 and docs[-3] == docs[-1] else ""
    if SYMBOL.search(cur):
        return carry, 0.3
    if not VARIABLE.fullmatch(cur) or cur in WORDS:
        return carry, -0.035
    letter = cur[-1]
    lower = letter.islower()
    if ARGUMENT.fullmatch(cur) and NAME.fullmatch(prev):
        if two_back in DEFINERS:
            return carry, 24.0  # the x in "Let f(x) = ..."
        return carry, 2.3 if lower else 0.9  # the x in f(x)
    if prev.endswith("_{") and two_back in INDEXED_BY:
        return carry, 11.0  # the index of a sum, product or limit
    if prev in BINDERS or prev.endswith("_{"):
        if letter in INDEXES:
            return carry, 5.6  # an index: for i, int i, sum_{i}
        return carry, 2.0 if lower else 0.6  # a variable being introduced: for x, Let x
    if prev in OPENERS or prev.endswith(("(", "[", "{")):
        if letter in INDEXES:
            return carry, 1.3  # an index right after an opening mark or ';' in a loop header
        return carry, 0.65 if lower else 0.4  # a variable right after an opening mark
    if letter == "x":
        return carry, 0.7
    return carry, 0.15 if lower else 0.08  # any other one-letter variable

"""Rough, mostly-unexplained model of layers.15.mlp.down_proj component 4733.

What it is: a single rank-one slice of layer 15's MLP output. It reads the MLP hidden
state mostly through hidden unit 4733 (about 38% of its read weight) and a long tail of
many small weights, so it behaves like a noisy, context-driven neuron. Its activation is
near 0 on most tokens (sd about 0.4), and most strongly negative on -ing verb forms that
start a phrase ("...that [being] outdoors", "...for [finding]", "...about [giving]").

What the program does: a few surface rules, no lookup table.
  - an -ing word after a clause opener (that, if, about, for, of, in, to, ...,
    or sentence punctuation): strongly negative;
  - any other -ing word: mildly negative;
  - function words (the, a, of, to, ...): slightly positive;
  - punctuation: slightly negative;
  - everything else: 0.
The values are rough means from training text. They explain only a few tenths of a
percent of the variance; token identity alone explains about 1%, and a wide linear model
of the preceding 8 to 64 tokens about 4%, so this is the largest share a simple reading
of the prefix captures.
"""

READS: tuple[str, ...] = ()

FUNCTION_WORDS = {
    "the", "a", "an", "of", "in", "to", "and", "or", "is", "are", "for", "on",
    "with", "that", "this", "it", "as", "by", "be", "from",
}
CLAUSE_OPENERS = {"that", "if", "about", "for", "of", "in", "to", "so", "like",
                  "actually", "In", "So", ".", "?", "!"}


def is_ing_word(word):
    return len(word) > 4 and word.isalpha() and word.lower().endswith("ing")


def is_punctuation(word):
    return word != "" and all(not ch.isalnum() for ch in word)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip() if same_doc else ""
    if is_ing_word(word):
        value = -0.8 if before in CLAUSE_OPENERS else -0.15
    elif word in FUNCTION_WORDS:
        value = 0.05
    elif is_punctuation(word):
        value = -0.03
    else:
        value = 0.0
    return carry, value
